🔬 Exploremos: construyendo la tabla conjunta


Code
prob &lt;- function(y1, y2) {
  if (y1 == 0) return(ifelse(y2 == -1, 1/8, 0))
  if (y1 == 1) return(ifelse(y2 == 1, 1/8, 0))
  if (y1 == 2) return(ifelse(y2 == 2, 1/8, 0))
  if (y1 == 3) return(ifelse(y2 == 3, 1/8, 0))
  return(0)
}

Y1 &lt;- 0:3
Y2 &lt;- c(-1, 1, 2, 3)
prob_matrix &lt;- outer(Y1, Y2, Vectorize(prob))
rownames(prob_matrix) &lt;- paste0("Y1=", Y1)
colnames(prob_matrix) &lt;- paste0("Y2=", Y2)
prob_matrix


     Y2=-1  Y2=1  Y2=2  Y2=3
